tl = get_builtin_value(param_name="tl")


def load_moler_configuration_from_tl():
    """
    Loading moler configuration before run function which needs moler configuration.
    Sample usage:
    from utilities import load_moler_configuration_from_tl

    @load_moler_configuration_from_tl()
    def some_method_which_use_moler_device(self):
        pass

    :return: wrapped function.
    """

    def inject_environment_params(func):
        origin_tl = get_builtin_value(param_name="tl")
        log_dir = os.path.join(get_builtin_value(param_name="OUTPUT DIR"), "moler")

        logger_params = {
            'PATH': log_dir,
            'DEBUG_LEVEL': "INFO"
        }

        decorated_func = load_moler_configuration(origin_tl,
                                                  create_at_startup=False,
                                                  logger_params=logger_params)(func)

        @wraps(func)
        def tl_wrapper(*args, **kwargs):
            return decorated_func(*args, **kwargs)

        return tl_wrapper

    return inject_environment_params


def load_default_moler_configuration():
    """
    Load basic moler configuration with devices:
        UnixLocal
        TEST_PC
    """
    config = {}
    log_dir = os.path.join(get_builtin_value(param_name="OUTPUT DIR"), "moler")
    logger_params = {
        'PATH': log_dir,
        'DEBUG_LEVEL': "INFO"
    }
    mc = MolerConverter()
    mc._prepare_default_parameters(create_at_startup=False)
    mc._build_test_pc_configuration(tl=get_builtin_value(param_name="tl"))
    config.update(mc.moler_devices.get_moler_device_config())
    config.update(mc._build_logger_configuration(params=logger_params))
    load_config(config=config, config_type='dict')


def load_custom_taf_testline_configuration_file(taf_tl_config_file):
    """
    Load custom TAF testline configuration file(taf.config.testline) during suite execution. Please use it careful.
    Could be used when SCF configuration is changed - especially when number of configured RUs are changed.
    In other cases please double-check if it is really needed - It could lead to unexpected behavior.
    If custom configuration is significant(e.g. full rack vs half rack), please use it in the
    Suite Setup instead of in Test Setup

    :param taf_tl_config_file:  TAF testline configuration file name('.py' ext is not required) or full path to file.
                                If only file name is given then file will be searched in the
                                testline_configuration/<testline_name> directory.
    """
    global tl
    if not get_builtin_value(param_name="ORIGIN_TAF_TL_CONFIG"):
        raise Exception("ORIGIN_TAF_TL_CONFIG variable not set. "
                        "Please use 'backup_origin_taf_testline_configuration' first")
    if os.path.exists(taf_tl_config_file):
        file_path = taf_tl_config_file
    else:
        config_dir = get_testline_configuration_directory_path()
        if '.py' not in taf_tl_config_file:
            taf_tl_config_file_old = os.path.join(config_dir, taf_tl_config_file)
            taf_tl_config_file = os.path.join(config_dir, taf_tl_config_file.split('.')[0] + '.py')
            shutil.copyfile(taf_tl_config_file_old, taf_tl_config_file)
        file_path = os.path.join(config_dir, taf_tl_config_file)

    logging.warning("Loading custom TAF testline configuration file: {}".format(file_path))
    import_variable_file_to_robot_framework_namespace(file_path)
    if tl is not get_builtin_value(param_name="tl"):
        tl = get_builtin_value(param_name="tl")

    # Clear and load moler configuration
    clear_moler_config()
    just_name = os.path.basename(taf_tl_config_file).split('.')[0]
    log_dir = os.path.join(get_builtin_value("OUTPUT DIR"), "moler", just_name)
    os.makedirs(log_dir, exist_ok=True)
    logger_params = {'PATH': log_dir, 'DEBUG_LEVEL': "INFO"}
    prepare_and_load_configuration(tl, create_at_startup=False, logger_params=logger_params)
    save_moler_configuration_to_yml_file()

    # What about already opened connections? eg to ADMIN CLI


def backup_origin_taf_testline_configuration():
    """
    Backup original TAF testline configuration to ORIGIN_TAF_TL_CONFIG variable.
    """
    set_robot_global_variable('ORIGIN_TAF_TL_CONFIG', tl)


def restore_origin_taf_testline_configuration():
    """
    Restore original TAF testline configuration from ORIGIN_TAF_TL_CONFIG variable.
    """
    global tl
    origin_taf_tl_config = get_builtin_value(param_name="ORIGIN_TAF_TL_CONFIG")
    if origin_taf_tl_config:
        logging.debug("ORIGIN_TAF_TL_CONFIG defined")
        set_robot_global_variable('tl', origin_taf_tl_config)
        if tl is not origin_taf_tl_config:
            tl = origin_taf_tl_config


def get_configuration(log_warning=True):
    """
    Get testline configuration from CONFIGURATION variable.
    :param log_warning: If True, logs a warning if CONFIGURATION is not defined.
    :return: tuple of (location, testline_name) if CONFIGURATION is defined, otherwise None.
    """
    configuration = get_builtin_value('CONFIGURATION')
    if configuration:
        location, testline_name = configuration.split('.')
        return location, testline_name
    if not configuration and log_warning:
        logging.warning("CONFIGURATION not defined. Please run your test with CONFIGURATION variable eg: "
                        "-v CONFIGURATION:Krakow.7_7CLOUDT459")


def get_testline_name_from_hostname(raw=False, device_name='TEST_PC'):
    """
    Returns testline's hostname.
    :param: the method returns raw hostname if it is True, otherwise hostname will be formatted as example shows:
        '7-7-UTE5GCLOUDT4SK059' for '7-7-UTE5GCLOUDT4SK059' if 'raw' parameter is set to False
    :return: hostname
    """
    from taf.rfrl.utilities.ute_vm.vm_operations import get_test_pc_hostname
    hostname = get_test_pc_hostname(device_name)
    if not raw:
        hostname = hostname.replace('-', '_').rstrip('_integration').upper()
        # 7_7_UTE5GCLOUDT8SK066_1
        hostname = re.sub(r'_\d+$', '', hostname)
    return hostname


def get_testline_name():
    """
    Get testline name from configuration or from hostname if configuration is not available.
    :return: testline name
    """
    configuration = get_configuration(log_warning=False)
    if configuration:
        logging.debug("Getting testline name from configuration")
        testline_name = configuration[1]
    else:
        logging.debug("Getting testline name from VM name")
        testline_name = get_testline_name_from_hostname()

    return testline_name


def get_testline_configuration_directory_path():
    """
    Get testline configuration directory path. Checking -V, -A options if not found then default location is returned.
    """
    sa = sys.argv
    default_repository_path = '/home/ute/testline_configuration/'
    config_dir = None
    if '-V' in sa or '--variablefile' in sa:
        for i in range(len(sa)):
            if sa[i] in ['-V', '--variablefile'] and 'testline_configuration' in sa[i + 1]:
                config_dir = sa[i + 1]
                break
    elif '-A' in sa or '--argumentfile' in sa:
        arg_name = '-A' if '-A' in sa else '--argumentfile'
        arg_file = sa[sa.index(arg_name) + 1]
        with open(arg_file, 'r+') as af:
            for line in af:
                try:
                    param, param_value = line.split()
                except ValueError:
                    continue
                if param == '-V' and 'testline_configuration' in param_value:
                    config_dir = param_value
                    break

    if config_dir is None:
        config_dir = os.path.join(default_repository_path, get_testline_name())
    if os.path.isfile(config_dir):
        config_dir = os.path.dirname(config_dir)

    return config_dir


def update_bts_mplane_ip(oam_ip, bts_type='GNB', bts_id=0, du_id=0):
    """
    Update runtime BTS mplane ip

    :param oam_ip: New oam ip address
    :param bts_type: BTS type: GNB or ENB
    :param bts_id: Id of BTS
    :param du_id: Id of DistributionUnit
    """
    if bts_type == 'GNB':
        tl.gnbs[bts_id].dus[du_id].oam_ip = oam_ip
        tl.gnbs[bts_id].cu.oam_http_connection_details.addr = oam_ip
    else:
        tl.enbs[bts_id].oam_ip = oam_ip


def get_all_bts_and_du_ids(bts_type='GNB'):
    btss = tl.gnbs if bts_type == 'GNB' else tl.enbs
    if not btss:
        return []
    du_ids = []
    for bts_id, bts in enumerate(btss, 0):
        if hasattr(bts, 'dus'):
            for du_id, du in enumerate(bts.dus, 0):
                du_ids.append({'bts_id': bts_id, 'du_id': du_id})
        else:
            du_ids.append({'bts_id': bts_id, 'du_id': 0})
    return du_ids


def get_web_credentials_for_du(bts_id=0, du_id=0, bts_type='GNB', ip_version=None):
    """
    Get WEB credentials for du.

    :param bts_id: Id of BTS
    :param du_id: Id of DistributionUnit
    :param bts_type: BTS type: GNB or ENB
    :param ip_version: IP Version: V4 or V6

    :return: (dict) wiht `ip`, `port`, `username` and `password`
    :rtype: dict
    """

    credentials = {}
    bts = _get_bts_object(bts_id=bts_id, bts_type=bts_type)

    if isinstance(bts, ClassicalBts):
        credentials = {
            'ip': _extract_ip_addr(bts.cu.oam_http_connection_details.addr),
            'username': bts.cu.oam_http_connection_details.username,
            'password': bts.cu.oam_http_connection_details.password,
            'port': bts.cu.oam_http_connection_details.port,
        }
    elif isinstance(bts, CloudBts):
        du = bts.dus[du_id]
        default_ip = '192.168.255.129'
        if hasattr(du, 'oam_ip'):
            if isinstance(du.oam_ip, str) or isinstance(du.oam_ip, NetworkAddress):
                oam_ip = _extract_ip_addr(du.oam_ip, ip_version)
            else:
                oam_ip = default_ip
        else:
            oam_ip = default_ip
        credentials = {
            'ip': oam_ip,
            'username': 'Nemuadmin',
            'password': 'nemuuser',
            'port': 443,
        }
    elif isinstance(bts, RealEnb):
        credentials = {
            'ip': _extract_ip_addr(bts.oam_ip, ip_version),
            'username': 'Nemuadmin',
            'password': 'nemuuser',
            'port': 443
        }
    return credentials


def _extract_ip_addr(ip_addr, ip_version=None):
    if isinstance(ip_addr, NetworkAddress):
        if ip_version is not None:
            ip_version = ip_version.lower()
            ip_addr = getattr(ip_addr, ip_version, None).split('/')[0]
        else:
            if getattr(ip_addr, 'v4', None):
                ip_addr = ip_addr.v4.split('/')[0]
            elif getattr(ip_addr, 'v6', None):
                ip_addr = ip_addr.v6
    else:
        ip_addr = ip_addr.split('/')[0]
    return ip_addr


def get_web_credentials_for_cu(bts_id=0, bts_type='GNB'):
    """
    Get WEB credentials for du.

    :param bts_id: Id of BTS
    :param bts_type: BTS type: GNB or ENB

    :return: sample results
    :rtype: dict
    """

    credentials = {}
    bts = _get_bts_object(bts_id=bts_id, bts_type=bts_type)

    if isinstance(bts, CloudBts):
        credentials = {
            'ip': bts.cu.oam_http_connection_details.addr,
            'username': bts.cu.oam_http_connection_details.username,
            'password': bts.cu.oam_http_connection_details.password,
        }

    return credentials


def _get_bts_object(bts_id, bts_type):
    btss = tl.gnbs if bts_type == 'GNB' else tl.enbs
    return btss[int(bts_id)]


def get_count_of_radios(bts_id=0, du_id=0, bts_type='GNB', common_unit_id=None, capacity_unit_id=None):
    """
    Get count of radios from configuration init file.

    :param bts_id: Id of BTS
    :param du_id: Id of DistributionUnit
    :param bts_type: BTS type: GNB or ENB
    :param common_unit_id: Id of Common Unit
    :param capacity_unit_id: Id of Capacity Unit

    :return: Radios count
    :rtype: int
    """
    bts = _get_bts_object(bts_id=bts_id, bts_type=bts_type)
    return len(_get_rus(bts=bts, du_id=du_id, bts_type=bts_type,
                        common_unit_id=common_unit_id, capacity_unit_id=capacity_unit_id))


def get_count_of_common_units(bts_id=0, du_id=0, bts_type='GNB'):
    """
    Get count of SMODs from configuration init file.

    :param bts_id: Id of BTS
    :param du_id: Id of DistributionUnit
    :param bts_type: BTS type: GNB or ENB

    :return: Capacity Units(eg: Abil) count
    :rtype: int
    """
    smods = _get_smods(bts_id=bts_id, du_id=du_id, bts_type=bts_type)
    return len(smods)


def get_count_of_capacity_units(bts_id=0, du_id=0, common_unit_id=0, bts_type='GNB'):
    """
    Get count of Ablis from configuration init file.

    :param bts_id: Id of BTS
    :param du_id: Id of DistributionUnit
    :param common_unit_id: Id of CommonUnit
    :param bts_type: BTS type: GNB or ENB

    :return: Capacity Units(eg: Abil) count
    :rtype: int
    """
    bts = _get_bts_object(bts_id=bts_id, bts_type=bts_type)

    airscale = _get_airscale_object(bts=bts, du_id=du_id)
    return len(airscale.common_units[int(common_unit_id)].capacity_units)


def get_count_of_distributed_units(bts_id=0, bts_type='GNB'):
    """
    Get count of Ablis from configuration init file.

    :param bts_id: Id of BTS
    :param bts_type: BTS type: GNB or ENB

    :return: Distributed Units count
    :rtype: int
    """
    bts = _get_bts_object(bts_id=bts_id, bts_type=bts_type)
    if isinstance(bts, CloudBts):
        return len(bts.dus)
    else:
        return 1


def _get_airscale_object(bts, du_id):
    airscale = None
    if hasattr(bts, 'dus') and bts.dus and isinstance(bts.dus[int(du_id)].airscale, Airscale):
        airscale = bts.dus[int(du_id)].airscale
    elif hasattr(bts, 'system_module') and isinstance(bts.system_module, Airscale):
        airscale = bts.system_module
    elif hasattr(bts, 'airscale') and isinstance(bts.airscale, Airscale):
        airscale = bts.airscale
    return airscale


def _get_smods(bts_id=0, du_id=0, bts_type='GNB'):
    """
    Get SMODs from configuration init file.

    :param bts_id: Id of BTS
    :param du_id: Id of DistributionUnit
    :param bts_type: BTS type: GNB or ENB

    :return: Capacity Units(eg: Abil) count
    :rtype: int
    """
    bts = _get_bts_object(bts_id=bts_id, bts_type=bts_type)
    airscale = _get_airscale_object(bts=bts, du_id=du_id)
    smods = airscale.common_units if airscale.common_units else airscale.core_units
    return smods


def _get_pc_related_to_bts(bts, common_unit_id=0):
    lmp_unit = _get_lmp_unit(bts, common_unit_id)

    for test_pc in tl.test_pcs:
        for connection in test_pc.connections:
            defined_device = connection.device if isinstance(connection, Connection) else connection
            if defined_device in [lmp_unit]:
                return test_pc
    # for backward compatibility
    for test_pc in tl.test_pcs:
        for connection in test_pc.connections:
            defined_device = connection.device if isinstance(connection, Connection) else connection
            if defined_device in [bts]:
                return test_pc


def _get_lmp_unit(bts, common_unit_id=0):
    airscale = _get_airscale_object(bts, du_id=0)
    if airscale.common_units:
        return airscale.common_units[common_unit_id]
    if airscale.core_units:
        return airscale.core_units[common_unit_id]


def get_bts_ws_credentials(bts_id=0, du_id=0, common_unit_id=0, bts_type='GNB'):
    """
    Get credentials for workstation to BTS.

    :param bts_id: Id of BTS
    :param du_id: Id of DistributionUnit
    :param common_unit_id: Id of CommonUnit
    :param bts_type: BTS type: GNB or ENB

    :return: Dict of 'host', 'user', 'password'
    :rtype: dict
    """
    ws_credentials = dict.fromkeys(('host', 'user', 'password'))
    bts = _get_bts_object(bts_id=bts_id, bts_type=bts_type)

    try:
        test_pc = _get_pc_related_to_bts(bts, common_unit_id)

        ws_credentials['host'] = test_pc.default_ssh_connection_details.addr
        ws_credentials['user'] = test_pc.default_ssh_connection_details.username
        ws_credentials['password'] = test_pc.default_ssh_connection_details.password

        return ws_credentials

    except AttributeError:
        airscale = _get_airscale_object(bts=bts, du_id=du_id)
        units = airscale.common_units if airscale.common_units else airscale.core_units
        cu = units[int(common_unit_id)]

        if hasattr(cu.lmp_connection, "proxy") and cu.lmp_connection.proxy is not None:
            ws_credentials['host'] = cu.lmp_connection.proxy.addr
            ws_credentials['user'] = cu.lmp_connection.proxy.username
            ws_credentials['password'] = cu.lmp_connection.proxy.password
        else:
            ws_credentials['host'] = tl.test_pc.default_ssh_connection_details.addr
            ws_credentials['user'] = tl.test_pc.default_ssh_connection_details.username
            ws_credentials['password'] = tl.test_pc.default_ssh_connection_details.password

        return ws_credentials


def get_global_bts_id(bts_id=0, du_id=0, bts_type='GNB'):
    """
    Get global BTS id from config file.

    :param bts_id: Id of BTS
    :param du_id: Id of DistributionUnit
    :param bts_type: BTS type: GNB or ENB

    :return: global BTS ID, nrbts_id for GNB or lnbts_id for ENB
    :rtype: int
    """

    bts = _get_bts_object(bts_id=bts_id, bts_type=bts_type)
    if isinstance(bts, CloudBts) and hasattr(bts.dus[int(du_id)], 'global_bts_id'):
        global_bts_id = bts.dus[int(du_id)].global_bts_id
    else:
        global_bts_id = bts.global_bts_id

    return global_bts_id


def get_bts_instance_id(bts_id=0, du_id=0, bts_type='GNB'):
    """
    Get BTS Instance id from config file.

    :param bts_id: Id of BTS
    :param du_id: Id of DistributionUnit
    :param bts_type: BTS type: GNB or ENB

    :return: global BTS ID - MRBTS
    :rtype: int
    """

    bts = _get_bts_object(bts_id=bts_id, bts_type=bts_type)
    if isinstance(bts, CloudBts) and hasattr(bts.dus[int(du_id)], 'instance_id'):
        instance_id = bts.dus[int(du_id)].instance_id
    else:
        instance_id = bts.instance_id

    return instance_id


def get_oam_ip_address(bts_id=0, du_id=0, bts_type='GNB'):
    """
    Get OAM IP address from configuration init file.

    :param bts_id: Id of BTS
    :param du_id: Id of DistributionUnit
    :param bts_type: BTS type: GNB or ENB

    :return: OAM IP address
    :rtype: string
    """
    bts = _get_bts_object(bts_id=bts_id, bts_type=bts_type)
    if isinstance(bts, CloudBts) and hasattr(bts.dus[int(du_id)], 'oam_ip'):
        oam_ip = bts.dus[int(du_id)].oam_ip
    elif isinstance(bts, RealEnb):
        oam_ip = bts.oam_ip
    else:
        oam_ip = bts.cu.backhaul_site_oam_ip

    return _extract_ip_addr(oam_ip)


def get_count_of_ru_extensions(bts_id=0, du_id=0, ru_id=0, bts_type='GNB'):
    """
    Get count of RU extension module from configuration init file.

    :param bts_id: Id of BTS
    :param du_id: Id of DistributionUnit
    :param ru_id: Id of Radio Unit
    :param bts_type: BTS type: GNB or ENB

    :return: Capacity Units(eg: Abil) count
    :rtype: int
    """
    bts = _get_bts_object(bts_id=bts_id, bts_type=bts_type)

    extensions = bts.dus[int(du_id)].rus[int(ru_id)].ru_extensions
    count_of_extensions = 0 if extensions is None else len(extensions)
    return count_of_extensions


def get_extension_product_code(bts_id=0, du_id=0, ru_id=0, ext_id=0, bts_type='GNB'):
    """
    Get product code of RU extension module from configuration init file.

    :param bts_id: Id of BTS
    :param du_id: Id of DistributionUnit
    :param ru_id: Id of Radio Unit
    :param ext_id: Id of Extension Module - related to test line configuration, default 0
    :param bts_type: BTS type: GNB or ENB

    :return: product code of extension module or None if no extension configured
    :rtype: string
    """
    bts = _get_bts_object(bts_id=bts_id, bts_type=bts_type)

    extensions = bts.dus[int(du_id)].rus[int(ru_id)].ru_extensions
    product_code = None if extensions is None else extensions[ext_id].product_code
    return product_code


def get_bts_pdu_port(bts_id=0, du_id=0, common_unit_id=0, bts_type='GNB'):
    """
    Get BTS PDU port from config file.

    :param bts_id: Id of BTS
    :param du_id: Id of DistributionUnit
    :param common_unit_id: Id of CommonUnit
    :param bts_type: BTS type: GNB or ENB

    :return:  one of the taf.pdu classes objects.
    :rtype: pdu object
    """

    bts = _get_bts_object(bts_id=bts_id, bts_type=bts_type)
    airscale = _get_airscale_object(bts=bts, du_id=du_id)
    return airscale.common_units[int(common_unit_id)].pdu_port if airscale.common_units else \
        airscale.core_units[int(common_unit_id)].pdu_port


def _fetch_radios(bts_id, du_id, bts_type, common_unit_id=None, capacity_unit_id=None):
    """
    Private helper function to fetch radios based on BTS and DU IDs.

    :param bts_id: Id of BTS
    :param du_id: Id of DistributionUnit
    :param bts_type: BTS type: GNB or ENB
    :param common_unit_id: Id of Common Unit
    :param capacity_unit_id: Id of Capacity Unit

    :return: List of Radio objects
    :rtype: list[Radio]
    """
    bts = _get_bts_object(bts_id=bts_id, bts_type=bts_type)
    return _get_rus(bts=bts, du_id=du_id, bts_type=bts_type,
                    common_unit_id=common_unit_id, capacity_unit_id=capacity_unit_id)


