def map_tl_radios_serial_number_with_id(radio_tl_objects):
    """
    Maps Radio Unit (RU) serial numbers to their corresponding IDs based on TL configuration.

    This mapping is useful for matching BTS configuration with TL configuration, i.e. during operations such as
    Power Cycle, it ensures that the correct port from the TL configuration is selected based on the BTS configuration

    :param radio_tl_objects: List of Radio Unit objects from config file
    :type radio_tl_objects: list

    :return: Dictionary mapping RUs serial numbers with IDs
    :rtype: dict
    """
    return {ru.serial_number: ru_id for ru_id, ru in enumerate(radio_tl_objects)}


