def _get_rus(bts, du_id=0, bts_type='GNB', common_unit_id=None, capacity_unit_id=None):
    if bts_type == 'GNB':
        rus = _get_rus_from_airscale(bts, du_id, common_unit_id, capacity_unit_id)
        if not rus:
            rus = bts.dus[int(du_id)].rus if bts.dus[int(du_id)].rus else []
        return rus
    else:
        if bts.rms:
            return bts.rms
        else:
            return _get_rus_from_airscale(bts, du_id, common_unit_id, capacity_unit_id)


def _get_rus_from_airscale(bts, du_id=0, common_unit_id=None, capacity_unit_id=None):
    rus = []
    airscale = _get_airscale_object(bts=bts, du_id=du_id)
    cus = airscale.common_units
    core = getattr(airscale, 'core_units')
    if cus:
        rus = __get_ru_under_capacity_unit(cus, common_unit_id, capacity_unit_id)
        if not rus:
            rus = __get_ru_under_common_unit(cus, common_unit_id)
    elif core:
        rus = __get_ru_under_core_unit(core, common_unit_id)
    return rus


def __get_ru_under_capacity_unit(cus, common_unit_id, capacity_unit_id):
    if common_unit_id is None:
        rus = [ru for cu in cus for cap_unit in cu.capacity_units for ru in (cap_unit.rus or [])]
    elif capacity_unit_id is None:
        cu = cus[int(common_unit_id)]
        rus = [ru for cap_unit in cu.capacity_units for ru in (cap_unit.rus or [])]
    else:
        cu = cus[int(common_unit_id)]
        rus = cu.capacity_units[int(capacity_unit_id)].rus or []

    unique_rus = []
    for ru in rus:
        if ru.serial_number not in [_ru.serial_number for _ru in unique_rus]:
            unique_rus.append(ru)

    return unique_rus


def __get_ru_under_common_unit(cus, common_unit_id):
    if common_unit_id is None:
        rus = [ru for cu in cus for ru in (cu.rus or [])]
    else:
        cu = cus[int(common_unit_id)]
        rus = cu.rus or []

    return rus


def __get_ru_under_core_unit(cus, core_unit_id):
    if core_unit_id is None:
        rus = [ru for cu in cus for ru in (cu.rus or [])]
    else:
        cu = cus[int(core_unit_id)]
        rus = cu.rus or []

    return rus


def get_du_lmp_credentials(bts_id=0, du_id=0, bts_type='GNB', common_unit_id=0):
    """
    Get credentials for the DU LMP connection

    :param bts_id: Id of BTS
    :param du_id: Id of DistributionUnit
    :param bts_type: BTS type: GNB or ENB
    :param common_unit_id: Id of CommonUnit

    :return:  DU LMP connection credentials
    :rtype:  dict
    """

    bts = _get_bts_object(bts_id=bts_id, bts_type=bts_type)
    airscale = _get_airscale_object(bts=bts, du_id=du_id)
    cu = airscale.common_units[common_unit_id] if airscale.common_units else airscale.core_units[common_unit_id]

    credentials = {
        'username': cu.lmp_connection.username,
        'password': cu.lmp_connection.password,
        'host': cu.lmp_connection.addr
    }

    return credentials


def get_ru_ws_credentials(bts_id=0, du_id=0, ru_id=0, bts_type='GNB', common_unit_id=None, capacity_unit_id=None):
    """
    Get credentials for the RU LMP connection

    :param bts_id: Id of BTS
    :param du_id: Id of DistributionUnit
    :param ru_id: Id of RU
    :param bts_type: BTS type: GNB or ENB
    :param common_unit_id: Id of CommonUnit
    :param capacity_unit_id: Id of CapacityUnit

    :return:  DU LMP connection credentials
    :rtype:  dict
    """

    ws_credentials = dict.fromkeys(('host', 'user', 'password'))
    ru = get_radio(bts_id=bts_id, du_id=du_id, ru_id=ru_id, bts_type=bts_type,
                   common_unit_id=common_unit_id, capacity_unit_id=capacity_unit_id)

    ws_credentials['host'] = ru.lmp_connection.proxy.addr
    ws_credentials['user'] = ru.lmp_connection.proxy.username
    ws_credentials['password'] = ru.lmp_connection.proxy.password
    return ws_credentials


def is_testline_of_cloud_type(bts_id=0, bts_type='GNB'):
    """
        Check if  testline is Cloud configuration

       :param bts_id: Id of BTS
       :param bts_type: BTS type: GNB or ENB

       :return: True or False
       :rtype: bool
       """
    bts = _get_bts_object(bts_id=bts_id, bts_type=bts_type)
    if isinstance(bts, CloudBts):
        return True
    return False


