@load_moler_configuration_from_tl()
def add_capacity_unit_subdevices_to_already_loaded_configuration(testline=tl, bts_id=0):
    """
    Add Capacity Unit subdevices ( MASTER, SLAVE, LONER ) to the moler configuration.
    :param testline:  Testline configuration
    :param bts_id:    Id of BTS
    :return:          Adds subdevices to the configuration
    """
    mc = MolerConverter()
    _add_capacity_unit_subdevices_configuration(testline=testline, mc=mc, bts_id=bts_id)
    all_devices = mc.moler_devices.get_moler_device_config()['DEVICES']
    return add_device_to_already_loaded_configuration(config=all_devices)


def _get_subdevices_ips(common_unit_type, bts_id=0, du_id=0):
    """
    Get IPs list for Capacity Unit subdevices from /etc/hosts file from Common Unit
    :param common_unit_type:    Common Unit type of hardware, eg. ASIK, ASOD
    :param bts_id:    Id of BTS
    :param du_id:     Id of DistributionUnit
    :return:          List of IPs
    """
    ret_ips = []
    cap_unit_num = get_count_of_capacity_units(bts_id=bts_id, du_id=du_id)
    # 192.167.253.36 fsp-2-5a fsp1_a fsp1   # asik
    # 192.168.253.16 fct-1-01 fct-boot      # asod
    # fd5f:4268:2387:a881:0040:43ff:fe80:0101 fsp-1a
    _re_sub_device_ip_asik = re.compile(r"(?P<IP>(\d{1,3}\.){3}\d{1,3}|([\da-fA-F]{1,4}:){7}[\da-fA-F]{1,4})"
                                        r"\s+fsp(\-\d){2}[abc].*")
    _re_sub_device_ip_asod = re.compile(r"(?P<IP>(\d{1,3}\.){3}\d{1,3}|([\da-fA-F]{1,4}:){7}[\da-fA-F]{1,4})"
                                        r"\s+fct(\-\d){2}[abc].*")
    _re_str = _re_sub_device_ip_asod if common_unit_type.lower() == 'asod' else _re_sub_device_ip_asik
    gnb = DeviceFactory.get_device("GNB{}_DU{}".format(bts_id, du_id))
    cat_lines = gnb.get_cmd(cmd_name="cat",
                            cmd_params={"path": "/etc/hosts"})()['LINES']
    for line in cat_lines:
        if re.match(_re_str, line):
            ret_ips.append(re.match(_re_str, line).group('IP'))
        if len(ret_ips) // 3 == cap_unit_num:
            logging.debug("Subdevices' IPs gathered from /etc/hosts:\n{}".format(ret_ips))
            return ret_ips


def _add_capacity_unit_subdevices_configuration(testline, mc, bts_id=0):
    """
    Build the Capacity Units subdevices for moler configuration
    :param testline:    Testline configuration
    :param mc:          MolerConverter object
    :param bts_id:      Id of BTS
    """
    test_pc_ssh = testline.test_pc.default_ssh_connection_details
    gnb = _get_bts_object(bts_id=bts_id, bts_type='GNB')
    for distribution_unit_id, du in enumerate(gnb.dus, 0):
        for common_unit_id, cu in enumerate(du.airscale.common_units, 0):
            ips = _get_subdevices_ips(common_unit_type=cu.hardware_type, bts_id=bts_id, du_id=distribution_unit_id)
            for capacity_unit_id, cap_u in enumerate(cu.capacity_units, 0):
                for sub_id, subdevice in enumerate(['MASTER', 'SLAVE', 'LONER'], 0):
                    device_name = 'GNB{}_DU{}_CU{}_CPTY{}_{}'.format(bts_id, distribution_unit_id, common_unit_id,
                                                                     capacity_unit_id, subdevice)
                    try:
                        proxy_params = mc._get_proxy_params(lmp_connection=cu.lmp_connection,
                                                            test_pc_connection=test_pc_ssh)
                        mc._add_airscale_configuration(cu, device_name, proxy_params, capacity_unit_id, 'FSP')
                        device_config = mc.moler_devices.get_moler_device_config()['DEVICES'][device_name]
                        device_config['CONNECTION_HOPS']['FCT']['FSP']['command_params']['host'] =\
                            ips[sub_id + capacity_unit_id * 3]
                    except (KeyError, AttributeError, TypeError) as ex:
                        mc.logger.warning(mc._parse_output_message(exception=ex, device_name=device_name))


def get_dcap_connection_details(bts_id=0):
    try:
        dcap_connection = tl.gnbs[bts_id].dcap.connection_details
    except AttributeError:
        raise TlConfigurationError("DCAP connection details not defined in TL configuration file.\n"
                                   "Example configuration for DCAP on UTE VM `DcapBasic(connection_details = "
                                   "HttpConnectionDetails('127.0.0.1', port=9443, username='dcapuser', "
                                   "password='dcapadmin!'))`")
    return dcap_connection


class TlConfigurationError(Exception):
    """Exception raised for error in Testline Configuration"""
    pass
